import{_ as s,l as i,o as e,c as l,v as r,p as n,x as t,d as c,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"脉动阵列","description":"","frontmatter":{"title":"脉动阵列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/systolic-array.md","filePath":"cs/systolic-array.md","lastUpdated":1789023840000}'),p={name:"cs/systolic-array.md"};function h(m,a,A,_,u,B){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="脉动阵列" tabindex="-1">脉动阵列 <a class="header-anchor" href="#脉动阵列" aria-label="Permalink to &quot;脉动阵列&quot;">​</a></h1><div class="epigraph"><p>数据沿阵列的边拍拍推进，每个单元做一次乘加再把数递给邻居；控制极简，带宽花在边界上而不是每拍从寄存器堆广播。</p><footer>—— 据 Kung and Leiserson；Kung, Why Systolic Architectures?, IEEE Computer 1982 整理</footer></div><p><a href="/cs/memory-coalescing">上一课</a> 仍每拍从存储子系统拉 warp 的横截面。矩阵乘一类核：同一行被许多列复用。本课不重讲 coalescing 分桶。缺口是 <strong>脉动阵列：把复用变成空间上的邻接传递</strong>，单元间寄存器即可，不必每次回 <a href="/cs/gpu-memory-hierarchy">HBM</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(C+=A\\times B\\) 的每个 \\(A\\) 元素被用 \\(K\\) 次。SIMD/SIMT 仍要反复读寄存器或 shared。缺口不是更大的 warp，而是<strong>网格上的 PE：左邻的数向右流、上邻的数向下流，本地 MAC 常驻。</strong> 控制流几乎没有，<a href="/cs/warp-divergence">发散</a> 不存在。</p><p><span class="marginnote">Kung 的 systolic：数据像血液被泵过阵列。当代矩阵单元（各种 MMA）是这一思想的密集实现；本课讲结构，不写某公司指令名当产品手册。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>PE \\((i,j)\\) 每拍：收下 \\(a\\)、\\(b\\)，做 \\(c\\leftarrow c+a\\cdot b\\)，把 \\(a\\)、\\(b\\) 传给指定邻居。阵列边界从存储器或缓冲注入流。填充与排空要若干拍，对应向量机的流水启动。</p>',8)),(e(),n(E,null,{default:t(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22A%20%E4%BB%8E%E5%B7%A6%E6%B5%81%E5%85%A5%22%5D%20--%3E%20PE%5B%22PE%20%E4%B9%98%E5%8A%A0%22%5D%0A%20%20B%5B%22B%20%E4%BB%8E%E4%B8%8A%E6%B5%81%E5%85%A5%22%5D%20--%3E%20PE%0A%20%20PE%20--%3E%20R%5B%22A%20%E5%90%91%E5%8F%B3%22%5D%0A%20%20PE%20--%3E%20D%5B%22B%20%E5%90%91%E4%B8%8B%22%5D%0A%20%20PE%20--%3E%20C%5B%22C%20%E9%A9%BB%E7%95%99%E6%88%96%E6%B5%81%E5%87%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>运算强度：边界带宽 \\(O(n)\\)、计算 \\(O(n^2)\\)（方阵示意），正是后课 Roofline 的高算术强度端。与 <a href="/cs/vector-lanes">向量 lane</a>：lane 共享指令、数据仍从 VRF 广播或 gather；脉动把数据路径硬化成邻居边。DSA 下一课把这种阵列（或相近的固定数据路径）封进领域加速器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把注意力矩阵乘的软件映射写进来。不规则图计算难以脉动。近存下一课解决的是「搬数据」另一极端：算子搬到 DRAM 边上，而不是在 PE 网格里流。</p><p>后课默认：规则稠密线性代数适合空间流水。把整条固定流水封成加速器，是 DSA。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>脉动阵列用邻接传递复用数据，控制极简。</li><li>启动排空是空间流水的气泡。</li><li>领域加速器把这种数据路径固化，下一课。</li><li>出处：Kung and Leiserson；Kung, <em>IEEE Computer</em>, 1982。</li></ul>',7))])}const g=s(p,[["render",h]]);export{P as __pageData,g as default};
